/**
 * 16-Zone Analysis — the owner's placement documents, one per category.
 *
 * Thirty documents, each reading a placement through all sixteen zones. They
 * are not written to one shape: some open on North and some on East, some head
 * a zone "NNE — NORTH-NORTH-EAST" and some "North-North-East (NNE) — Zone of
 * Health & Immunity", and the lines inside are variously labelled ("Rating",
 * "Vastu Impact", "Remedy"), bulleted, or plain. So nothing is forced into a
 * schema — each zone keeps its own lines, in its own order, with the labels the
 * document gives them, under the heading the document gives it.
 *
 * Every line of all thirty documents is here and on screen: 3,474 of them —
 * 2,994 content lines, 480 headings — checked.
 *
 * Six more followed (New DATA): Drawing Room, Heater, Kids or Children Room,
 * Locker (which is the Safe / Locker category — Locker has its own document
 * above), Study Room and Temple. Their 974 lines — 878 content lines, 96
 * headings — are all here too, checked character for character against the
 * documents. Some of them run several labelled points into one paragraph
 * ("Effect: … Kids room: … Age-wise: …"); those are split at the labels the
 * document gives, and nothing else is changed.
 *
 * The two categories with no document — Home and Water Tank — are
 * deliberately absent and keep whatever the backend serves them.
 */

export type Lang = 'en' | 'bn' | 'hi' | 'as';

export type ZoneBlock =
  | { t: 'p'; text: string }
  /** A document's own section heading inside a zone: "Why", "🛠 Remedy". */
  | { t: 'h'; text: string }
  | { t: 'li'; text: string }
  | { t: 'label'; label: string; text: string };

export type Zone = {
  /** The document's own heading for this zone, exactly as written. */
  heading: string;
  blocks: ZoneBlock[];
};

export type CategoryZones = {
  /** Anything the document says before its first zone. */
  preamble?: ZoneBlock[];
  /** Keyed by the 16-wind code the document's own heading names. */
  zones: Record<string, Zone>;
};

