/** Translations, added as they are written; anything absent falls back. */
const TRANSLATIONS: Partial<Record<Lang, Record<string, CategoryZones>>> = {};

function forLang(lang: Lang): Record<string, CategoryZones> {
  return TRANSLATIONS[lang] ?? ORIGINAL;
}

/**
 * Every category this file carries data for.
 *
 * Read from the data rather than written out by hand, so a tool walking the
 * whole corpus cannot quietly miss a category the way a copied list can.
 */
export const ZONE_CATEGORIES: string[] = Object.keys(ORIGINAL);

export function zoneAnalysis(slug?: string | null, dir16?: string | null, lang: Lang = 'en'): Zone | null {
  if (!slug || !dir16) return null;
  return forLang(lang)[slug]?.zones[dir16.toUpperCase()] ?? null;
}

/** Anything a document says before its first zone — its own title line. */
export function zonePreamble(slug?: string | null, lang: Lang = 'en'): ZoneBlock[] | null {
  if (!slug) return null;
  const pre = forLang(lang)[slug]?.preamble;
  return pre && pre.length ? pre : null;
}

/**
 * Where a zone stops describing and starts correcting.
 *
 * Every document puts its corrections last — checked across all 576 zones;
 * the one thing that follows them is the Safe / Locker document's closing
 * "Domestic: … Commercial: …" rating, which stays where the document put it —
 * but they are headed differently: "Remedy", "🛠 Remedy", "Relocation
 * Priority", "Relocation / Remedy", "Vastu Remedy:", "Enhancement", "Powerful
 * correction hierarchy", "Priority remedy sequence:", and in the Heater
 * document "If heater must be placed here" or "Better approach". A label is
 * matched on the word; a plain line only when it reads as a heading, so prose
 * that merely mentions a remedy does not split the zone early.
 *
 * 561 of the 576 zones carry corrections. The other 15 state none — they are
 * the ideal zones for that placement, where the document prescribes nothing.
 */
const REMEDY_LABEL = /remed|enhancement|relocation|correction|solution|precaution/i;
// Headings may open on a symbol ("🛠 Remedy"). The Heater document also turns
// to what to do with "If heater must be placed here", "Better approach" and
// the like rather than the word remedy.
const REMEDY_HEADING = new RegExp(
  '^[^A-Za-z]*(?:(vastu\\s+|priority\\s+|powerful\\s+|best\\s+|strong\\s+)?(remed(y|ies|ial)|correction|relocation|enhancement|solution)'
  + "|if (the )?heater (must|is unavoidable|is already)|if unavoidable$|if relocation isn't possible"
  + '|if the safe already exists|recommended approach|better approach|recommendation$|prefer:$)',
  'i',
);

function startsRemedy(b: ZoneBlock): boolean {
  return b.t === 'label' ? REMEDY_LABEL.test(b.label) : REMEDY_HEADING.test(b.text);
}

/** The zone's lines as the two tabs show them, in the document's own order. */
export function splitZone(zone: Zone | null): { effects: ZoneBlock[]; treatment: ZoneBlock[] } {
  if (!zone) return { effects: [], treatment: [] };
  const at = zone.blocks.findIndex(startsRemedy);
  if (at === -1) return { effects: zone.blocks, treatment: [] };
  return { effects: zone.blocks.slice(0, at), treatment: zone.blocks.slice(at) };
}
